import { Router } from "express";
import { z } from "zod";

import { requireAuth, requireRole } from "../middleware/auth.js";
import { validate } from "../utils/validate.js";
import { createExam, listExams } from "../controllers/exams.js";

export const examsRouter = Router();

examsRouter.get("/", requireAuth, requireRole(["admin", "teacher", "student"]), listExams);

examsRouter.post(
  "/",
  requireAuth,
  requireRole("admin"),
  validate(
    z.object({
      body: z.object({
        name: z.string().min(1),
        class_id: z.number().int().positive(),
        date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
      }),
    }),
  ),
  createExam,
);

